class Gradebook:
    def __init__(self) -> None:
        self.assignments = {}  # name -> (weight, kind)
        self.grades = {}  # student -> {assignment -> grade}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ["homework", "quiz"]:
            raise ValueError("kind must be 'homework' or 'quiz'")
        self.assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if grade < 2.0 or grade > 5.0:
            raise ValueError("Grade must be between 2.0 and 5.0")
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if student not in self.grades:
            # If student has no grades at all, compute average with all assignments as 2.0
            total_weighted_sum = 0.0
            total_weight = 0.0
            for assignment_name, (weight, kind) in self.assignments.items():
                total_weighted_sum += 2.0 * weight
                total_weight += weight
            return total_weighted_sum / total_weight if total_weight > 0 else 0.0

        # Get all assignments for this student
        student_grades = self.grades[student]

        # Separate homework and quiz grades
        homework_grades = {}
        quiz_grades = {}

        for assignment_name, (weight, kind) in self.assignments.items():
            if assignment_name in student_grades:
                if kind == "homework":
                    homework_grades[assignment_name] = student_grades[assignment_name]
                else:  # kind == "quiz"
                    quiz_grades[assignment_name] = student_grades[assignment_name]
            else:
                # Assignment not recorded, use default grade of 2.0
                if kind == "homework":
                    homework_grades[assignment_name] = 2.0
                else:  # kind == "quiz"
                    quiz_grades[assignment_name] = 2.0

        # Handle quiz dropping: if more than one quiz, drop the lowest
        if len(quiz_grades) > 1:
            # Find the quiz with the lowest grade
            lowest_quiz_grade = min(quiz_grades.values())
            # Drop one occurrence of the lowest grade
            dropped = False
            filtered_quiz_grades = {}
            for assignment_name, grade in quiz_grades.items():
                if not dropped and grade == lowest_quiz_grade:
                    dropped = True
                    continue
                filtered_quiz_grades[assignment_name] = grade
            quiz_grades = filtered_quiz_grades

        # Calculate weighted average
        total_weighted_sum = 0.0
        total_weight = 0.0

        # Add homework grades
        for assignment_name, grade in homework_grades.items():
            weight, _ = self.assignments[assignment_name]
            total_weighted_sum += grade * weight
            total_weight += weight

        # Add quiz grades
        for assignment_name, grade in quiz_grades.items():
            weight, _ = self.assignments[assignment_name]
            total_weighted_sum += grade * weight
            total_weight += weight

        return total_weighted_sum / total_weight if total_weight > 0 else 0.0
